def gaps(raw):
    """Five dielectric gaps L1-L2, L2-L3 (core), L3-L4, L4-L5 (core), L5-L6 in mm."""
    a, rest = raw.split('Inner Layer L2', 1)
    g1 = sum(float(x) for x in re.findall(r'Prepreg \S+ ([\d.]+)mm', a))
    m = re.search(r'Copper Core Copper 0\.03mm ([\d.]+)mm', rest)
    g2 = float(m.group(1))
    mid, rest2 = rest[m.end():].split('Inner Layer L4', 1)
    g3 = sum(float(x) for x in re.findall(r'(?:Prepreg \S+|Core Core) ([\d.]+)mm', mid))
    m2 = re.search(r'Copper Core Copper 0\.03mm ([\d.]+)mm', rest2)
    g4 = float(m2.group(1))
    tail = rest2[m2.end():]
    g5 = sum(float(x) for x in re.findall(r'Prepreg \S+ ([\d.]+)mm', tail))
    return [round(g, 4) for g in (g1, g2, g3, g4, g5)]


STACKS = {k: gaps(v) for k, v in RAW.items()}

if __name__ == '__main__':
    for k, g in sorted(STACKS.items()):
        tot = sum(g) + 2 * 0.035 + 4 * 0.03
        print('%-17s gaps %s  total %.3f mm' % (k, ' / '.join('%.3f' % x for x in g), tot))
